  Lemma zero_byte_read : forall (i : Z) mm,
    bytes_at bsegs mm A (zeros (Z.to_nat n)) -> 0 <= i < n ->
    ov_read_bytes bsegs mm (wa (A + i)) 1 = Some [Z_to_bv 8 0].
  Proof.
    intros i mm ZBm Hi. apply (u8ro_read bsegs mm A (zeros (Z.to_nat n)) i); [exact ZBm | apply zeros_nth; lia | lia | reflexivity].
  Qed.

