    (* [comment removed for export] *)
    Lemma miz_words : forall (k : nat) (q dn : Z) x13 x16,
      Z.to_nat (dn - q) = k -> dn mod 8 = 0 -> q mod 8 = 0 -> A <= q < dn -> A + n - 8 < dn <= A + n ->
